INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(29601, 'Revelation 2:16', 'Revelation', 2, 16, '&nbsp;نو توبه وباسه، کۀ نه نو زۀ به زر راشم او په هغه تُوره به د هغوئ سره جنګ وکړم کومه چې زما د خولې نه راوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29602, 'Revelation 2:17', 'Revelation', 2, 17, '&nbsp;د چا چې غوږونه وى، هغه دې واورى چې روحُ القُدس جماعتونو ته څۀ فرمائى. هر هغه څوک چې کامياب شى نو زۀ به هغوئ ته پټ شوى من او يو سپين کاڼے ورکړم او په هغه سپين کاڼى به يو نوے نوم ليکلے شوے وى چې صرف هغه چا ته يې پته ده چا ته چې دا کاڼے ورکړے شوے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29603, 'Revelation 2:18', 'Revelation', 2, 18, '&nbsp;د تواتيره د جماعت فرښتې ته دا پېغام وليکه چې د خُدائ پاک زوئ داسې فرمائى د چا سترګې چې د اور د شغلو په شان دى او چې پښې يې د زېړو په شان ځليږى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29604, 'Revelation 2:19', 'Revelation', 2, 19, '&nbsp;ما ته ستا د ټولو عملونو، ستا د مينې، ايماندارۍ، خدمت او صبر پته ده. ما ته پته ده چې ستا اوسنى عملونه ستا د مخکښينو عملونو نه بهتر دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29605, 'Revelation 2:20', 'Revelation', 2, 20, '&nbsp;خو زۀ ستا خلاف دا شکايت کوم چې تۀ هغه ايزبلى نومې ښځه برداشت کوې چې ځان ته پېغمبره وائى او زما خادِمانو ته د حرامکارۍ او د بُتانو د قربانۍ د خوړلو ترغيب ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29606, 'Revelation 2:21', 'Revelation', 2, 21, '&nbsp;ما هغې ته د توبې ويستلو موقع ورکړه خو هغه د خپلې حرامکارۍ نه توبه نۀ وباسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29607, 'Revelation 2:22', 'Revelation', 2, 22, '&nbsp;نو زۀ به هغه د کټ په رنځ وغورزوم او هغوئ چې ورسره يې زنا کړې ده، هغوئ به په ډېره سخته تنګسيا کښې راګېر کړم ترڅو چې هغوئ د هغې د کړو نه توبه ونۀ باسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29608, 'Revelation 2:23', 'Revelation', 2, 23, '&nbsp;او د هغې بچى به په زمکه ووژنم. په دې به ټول جماعتونه دا سبق حاصل کړى چې زۀ د بنى آدمو زړُونه او خيالات آزمائيم او دا چې زۀ به تاسو ټولو ته د خپل عمل په مطابق اجر درکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29609, 'Revelation 2:24', 'Revelation', 2, 24, '&nbsp;خو اے د تواتيره نورو اوسېدونکو چې دا تعليم نۀ منئ او د هغې نه ناخبره يئ کومې ته چې هغوئ د شېطان پټ او ژور چال وائى، زۀ تاسو ته وايم چې زۀ به په تاسو نور بار وانۀ چوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29610, 'Revelation 2:25', 'Revelation', 2, 25, '&nbsp;بس په هغه څۀ تر هغې ټينګ پاتې شئ ترڅو چې زۀ درنۀ شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29611, 'Revelation 2:26', 'Revelation', 2, 26, '&nbsp;هر هغه څوک چې کامياب شى او هغه چې زما د وينا په مطابق تر آخره عمل کوى نو زۀ به ورله په قومونو اختيار ورکوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29612, 'Revelation 2:27', 'Revelation', 2, 27, '&nbsp;هغه به پرې زورَور حکومت کوى او د خاورو د لوښو په شان به يې ټوټې ټوټې کړى. هغه اختيار ما ته د خپل پلار نه راکړے شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29613, 'Revelation 2:28', 'Revelation', 2, 28, '&nbsp;او زۀ به هغۀ له د سبا ستورے ورکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29614, 'Revelation 2:29', 'Revelation', 2, 29, '&nbsp;د چا چې غوږونه وى، هغه دې واورى چې روحُ القُدس جماعتونو ته څۀ فرمائى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29615, 'Revelation 3:1', 'Revelation', 3, 1, '&nbsp;”د سرديس د جماعت فرښتې ته دا پېغام وليکه، چا سره چې د خُدائ پاک اووۀ روحونه او اووۀ ستورى دى هغه دا وائى چې زۀ ستا په ټول عمل خبر يم چې تۀ تش په نوم ژوندے يې خو يې مړ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29616, 'Revelation 3:2', 'Revelation', 3, 2, '&nbsp;بېدار شه او څۀ چې پاتې دى، او مړ کېدو ته نزدې دى هغه مضبوط کړه، ستا کارونه هم ما د خپل خُدائ پاک په نظر کښې پوره ونۀ ليدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29617, 'Revelation 3:3', 'Revelation', 3, 3, '&nbsp;کوم تعليم چې تا ته درکړے شوے دے او تا اورېدلے دے، هغه ياد ساته او عمل پرې کوه او توبه وباسه. کۀ تۀ بېدار نۀ شې نو زۀ به د غل په شان درشم او تا ته به زما د راتلو د وخت پته ونۀ لګى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29618, 'Revelation 3:4', 'Revelation', 3, 4, '&nbsp;خو بيا هم په سرديس کښې تاسو سره ځينې داسې کسان شته چې هغوئ خپلې جامې پليتې کړې نۀ دى، هغوئ به ما سره په سپينو جامو کښې ګرځى ځکه چې هغوئ د دې لائق دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29619, 'Revelation 3:5', 'Revelation', 3, 5, '&nbsp;هر هغه څوک چې کامياب شى نو هغوئ ته به دغسې سپينې جامې وراغوستلے شى او د هغوئ نوم به زۀ هيڅکله هم د ژوندون د کِتاب نه ونۀ باسم او زۀ به د خپل پلار او د هغۀ د فرښتو د وړاندې دا اعلان وکړم چې هغوئ زما خپل دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29620, 'Revelation 3:6', 'Revelation', 3, 6, '&nbsp;د چا چې غوږونه وى، هغوئ دې واورى چې روحُ القُدس جماعتونو ته څۀ فرمائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29621, 'Revelation 3:7', 'Revelation', 3, 7, '&nbsp;د فيلدِلفيه د جماعت فرښتې ته دا پېغام وليکه، هغه څوک چې قُدوس او رښتينے دے داسې فرمائى چې ورسره د داؤد چابى ده او هغه چې دروازه کولاو کړى نو څوک به يې هم بنده نۀ کړى او چې هغه دروازه بنده کړى نو څوک به يې هم کولاو نۀ کړى، هغه داسې وائى چې', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29622, 'Revelation 3:8', 'Revelation', 3, 8, '&nbsp;زۀ ستا د ټولو عملونو نه خبر يم. وګوره، ما تا ته ستا په وړاندې يوه دروازه کولاو کړې ده چې هيڅوک يې بندولے نۀ شى. زۀ پوهېږم چې ستا طاقت کم دے خو بيا هم تا زما کلام منلے دے او زما د نوم نه منکر شوے نۀ يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29623, 'Revelation 3:9', 'Revelation', 3, 9, '&nbsp;ګوره، د شېطان د قبيلې نه به هغوئ راولم چې ځان ته يهوديان وائى خو نۀ دى بلکې دروغژن دى، هغوئ به درشى او ستا په پښو به پرېوځى او هغوئ به په دې پوهه شى چې تۀ زما محبوب يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29624, 'Revelation 3:10', 'Revelation', 3, 10, '&nbsp;ځکه چې تا زما کلام په صبر سره برداشت کړے دے او مضبوط پرې ولاړ يې، زۀ به هم تا د هغه آزمېښت د وخت نه چې د ټولې دُنيا په خلقو راتلونکے دے، بچ کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29625, 'Revelation 3:11', 'Revelation', 3, 11, '&nbsp;زۀ زر درځم او څۀ چې درسره دى په هغې ټينګ پاتې شه چې څوک دې هم د خپل تاج نه محرومه نۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29626, 'Revelation 3:12', 'Revelation', 3, 12, '&nbsp;هر هغه څوک چې کامياب شى نو هغوئ به زما د خُدائ د کور ستن شى، او هغوئ به هر وخت په هغې کښې اوسيږى. زۀ به په هغوئ د خپل خُدائ نوم وليکم او هغوئ به زما د خُدائ پاک د ښار اوسېدونکى شى يعنې د نوې يروشلم کوم چې د آسمان نه ښکته راځى او زۀ به پرې خپل نوے نوم وليکم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29627, 'Revelation 3:13', 'Revelation', 3, 13, '&nbsp;د چا چې غوږونه وى، هغه دې واورى چې روحُ القُدس جماعتونو ته څۀ فرمائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29628, 'Revelation 3:14', 'Revelation', 3, 14, '&nbsp;د لوديکيه د جماعت فرښتې ته دا پېغام وليکه، دا پېغام د هغه چا د طرفه دے چې آمين دے، څوک چې وفادار رښتينے ګواه دے او د خُدائ پاک د نوى خلقت شروع ده. هغه فرمائى چې', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29629, 'Revelation 3:15', 'Revelation', 3, 15, '&nbsp;ما ته ستا د ټولو عملونو پته ده، تۀ خو نۀ يخ يې او نۀ ګرم. کاش چې تۀ يا خو يخ وے يا ګرم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29630, 'Revelation 3:16', 'Revelation', 3, 16, '&nbsp;نو چونکې نۀ خو تۀ ګرم يې او نۀ يخ، بلکې تړم يې، زۀ به تا د خپلې خولې نه وتُوکم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29631, 'Revelation 3:17', 'Revelation', 3, 17, '&nbsp;ځکه چې تۀ وائې چې زۀ مالدار او دولتمند يم او د څۀ څيز حاجتمند نۀ يم. حقه خو دا ده چې تۀ په دې نۀ پوهېږې چې تۀ څومره قابلِ رحم، بدنصيبه، خوار، ړوند او بربنډ يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29632, 'Revelation 3:18', 'Revelation', 3, 18, '&nbsp;په دې وجه زۀ تا له دا مشوره درکوم چې زما نه په اور کښې صفا شوى سرۀ زر واخله چې مالدار شې او سپينې جامې رانه واخله چې ستا د بربنډتوب شرم پرې د ليدو نه پټ شى، او ملهم رانه واخله چې په سترګو کښې يې ولګوې او بينا شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29633, 'Revelation 3:19', 'Revelation', 3, 19, '&nbsp;زۀ چې چا سره مينه کوم هغوئ ملامته کوم او تربيت ورکوم، نو ځکه غېرت وکړه او توبه وباسه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29634, 'Revelation 3:20', 'Revelation', 3, 20, '&nbsp;ګوره، زۀ په ور کښې ولاړ يم او ور وهم. او کۀ تۀ آواز اورې او ما ته ور کولاو کړې نو زۀ به درشم او يو بل سره به په شريکه روټۍ وخورو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29635, 'Revelation 3:21', 'Revelation', 3, 21, '&nbsp;هر څوک چې کامياب شى هغه به ما سره په تخت کښېنى، لکه څنګه چې زۀ په خپله کامياب شوم او د خپل پلار سره د هغۀ په تخت کښېناستم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29636, 'Revelation 3:22', 'Revelation', 3, 22, '&nbsp;د چا چې غوږونه وى، هغه دې واورى چې روحُ القُدس جماعتونو ته څۀ فرمائى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29637, 'Revelation 4:1', 'Revelation', 4, 1, '&nbsp;د دې نه وروستو بيا ما نظر واچولو نو په آسمان کښې مې يو ور کولاو وليدو. نو چې اول کوم آواز ما واورېدو نو لکه د بيګل په شان يې ما ته خبرې کولې، ”دلته پاس راشه چې زۀ به تا ته هغه وښايم څۀ چې به د دې نه پس خامخا کيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29638, 'Revelation 4:2', 'Revelation', 4, 2, '&nbsp;سمدستى د روحُ القُدس په وسيله ما يوه رويا وليدله چې په آسمان کښې يو تخت وو او په تخت يو کس ناست وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29639, 'Revelation 4:3', 'Revelation', 4, 3, '&nbsp;او هغه څوک چې هلته ناست وو د جاسپر او يمنى عقيق په شان پړقېدو، او د تخت نه چاپېره د بوډۍ ټال وو چې د زمرودو په شان پړقېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29640, 'Revelation 4:4', 'Revelation', 4, 4, '&nbsp;او د تخت نه ګېرچاپېره څليريشت نور تختونه وُو او په هغوئ څليريشت مشران ناست وُو چې سپينې جامې يې اغوستې وې او د سرو زرو تاجونه يې په سر وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29641, 'Revelation 4:5', 'Revelation', 4, 5, '&nbsp;او د تخت نه د برېښنا رڼا او د تندر آوازونه راختل او د تخت نه وړاندې اووۀ مشعلونه بلېدل چې د خُدائ پاک اووۀ روحونه دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29642, 'Revelation 4:6', 'Revelation', 4, 6, '&nbsp;او د تخت د وړاندې يې د شيشې سمندر وو چې د بلور په شان ښکارېدو. او د تخت نه چاپېره څلور جاندار وُو چې وړاندې وروستو يې سترګې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29643, 'Revelation 4:7', 'Revelation', 4, 7, '&nbsp;اول جاندار د ازمرى په شان وو، دوېم د غوائى په شان، د درېم مخ د بنى آدم په شان وو او څلورم لکه د الوتونکى باز په شان وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29644, 'Revelation 4:8', 'Revelation', 4, 8, '&nbsp;دې څلورو جاندارو چې د هر يو شپږ وزرې وې او هر طرف ته يې سترګې وې، شپه او ورځ بغېر د دمې يې دا ثنا وئيله، ”قُدوس، قُدوس، قُدوس، قادر مطلق خُدائ پاک، هغه چې وو، چې دے، او چې راتلونکے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29645, 'Revelation 4:9', 'Revelation', 4, 9, '&nbsp;او هرکله چې دا جاندار د هغه چا چې په تخت ناست دے او تل تر تله ژوندے دے، د هغۀ لوئى، عزت او شُکر ګزارى وکړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29646, 'Revelation 4:10', 'Revelation', 4, 10, '&nbsp;نو هغه څليريشت مشران هغۀ ته په سجده پرېوځى او عبادت يې کوى څوک چې په تخت ناست دے، او چې تل تر تله ژوندے دے، نو هغوئ خپل تاجونه د تخت په وړاندې هغۀ ته ږدى او وائى چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29647, 'Revelation 4:11', 'Revelation', 4, 11, '&nbsp;”اے زمونږ مالِکه خُدايه پاکه، تۀ د لوئى، عزت او قُدرت لائق يې ځکه چې تا هر څۀ پېدا کړى دى او دا ستا په مرضۍ پېدا شوى دى او په وجود کښې راغلى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29648, 'Revelation 5:1', 'Revelation', 5, 1, '&nbsp;هغه څوک چې په تخت ناست وو ما د هغۀ په ښى لاس کښې يو طومار وليدو چې دننه او بهر دواړو طرفو ته پرې ليکل وُو او اووۀ مهرونه پرې لګېدلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29649, 'Revelation 5:2', 'Revelation', 5, 2, '&nbsp;او ما يوه طاقتوره فرښته وليده چې په اوچت آواز يې اعلان کولو چې، ”څوک د دې قابل دے چې طومار پرانيزى او مهرونه يې مات کړى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29650, 'Revelation 5:3', 'Revelation', 5, 3, '&nbsp;خو هيڅوک هم نۀ وو، نۀ په آسمان کښې، نۀ په زمکه او نۀ د زمکې د لاندې وو چې طومار يې کولاو کړے وے او يا يې دننه کتلے وے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29651, 'Revelation 5:4', 'Revelation', 5, 4, '&nbsp;نو ما ډېر وژړل ځکه چې هيڅوک هم د دې لائق نۀ وو چې دا طومار يې پرانستلے شو يا چې يې ورته کتلے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29652, 'Revelation 5:5', 'Revelation', 5, 5, '&nbsp;بيا په مشرانو کښې يو راته ووئيل چې، ”ژاړه مه ځکه چې د يهوداه د قبيلې ازمرے چې د داؤد د نسل نه دے، هغه کاميابى حاصله کړې ده نو طومار به پرانيزى او اووۀ مهرونه به يې مات کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29653, 'Revelation 5:6', 'Revelation', 5, 6, '&nbsp;بيا ما د تخت په مينځ کښې او د څلورو جاندارو او د مشرانو په مينځ کښې يو لکه د حلال شوى ګډورى وليدو چې اووۀ ښکرونه او اووۀ سترګې يې وې چې د خُدائ پاک اووۀ روحونه دى چې ټولې دُنيا ته لېږلے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29654, 'Revelation 5:7', 'Revelation', 5, 7, '&nbsp;او هغه ورغلو او څوک چې په تخت ناست وو د هغۀ د ښى لاس نه يې هغه طومار واخستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29655, 'Revelation 5:8', 'Revelation', 5, 8, '&nbsp;کله چې هغۀ طومار واخستو نو څلور جاندار او څليريشت مشران د هغه ګډُورى په وړاندې په سجده شول، او د هر يو سره يو ستار وو او ورسره د خوشبويۍ نه ډک د سرو زرو جامونه وُو چې د مقدسينو دُعاګانې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29656, 'Revelation 5:9', 'Revelation', 5, 9, '&nbsp;او هغوئ دا نوے حمد وئيلو چې، ”تۀ د دې لائق يې چې طومار واخلې او د دې مهرونه کولاو کړې ځکه چې تۀ حلال کړے شوې او د خپلې وينې په فديه دې د خُدائ پاک دپاره د هر خيل، د هرې ژبې او د هر قوم او خلق په بيعه واخستل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29657, 'Revelation 5:10', 'Revelation', 5, 10, '&nbsp;او د هغوئ نه تا د اِمامانو بادشاهى جوړه کړه چې زمونږ د خُدائ پاک خِدمت وکړى او هغوئ به په زمکه بادشاهى کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29658, 'Revelation 5:11', 'Revelation', 5, 11, '&nbsp;بيا چې ما وکتل نو د بې‌شمېره فرښتو آوازونه مې واورېدل چې هغه د تخت او د جاندارو او د مشرانو نه چاپېره وې او د هغوئ شمېر په زرګونو او لکونو کښې وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29659, 'Revelation 5:12', 'Revelation', 5, 12, '&nbsp;او هغوئ په زوره سندرې وئيلې چې، ”هغه ګډُورے چې حلال کړے شو، د دې لائق دے چې ټول قُدرت، دولت، حِکمت، لوئى، عزت، جلال او برکت حاصل کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29660, 'Revelation 5:13', 'Revelation', 5, 13, '&nbsp;او بيا ما واورېدل چې ټول مخلوقات چې په آسمان کښې، په زمکه باندې، د زمکې د لاندې يا په سمندر کښې دى، هغوئ ټولو ثناء صِفت کولو چې، ”د هغه چا څوک چې په تخت ناست دے او ګډُورى ته برکت، عزت، شان او قُدرت دې تل تر تله وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29661, 'Revelation 5:14', 'Revelation', 5, 14, '&nbsp;او څلور واړو جاندارو پرې، ”آمين“ ووې او مشران د عبادت دپاره په سجده پرېوتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29662, 'Revelation 6:1', 'Revelation', 6, 1, '&nbsp;بيا ما وليدل چې هغه ګډُورى په اوو مهرونو کښې يو مهر مات کړو او ما د څلورو جاندارو نه په يو کښې د تندر په شان دا آواز واورېدو چې، ”راشه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29663, 'Revelation 6:2', 'Revelation', 6, 2, '&nbsp;نو ما وکتل چې هلته يو سپين آس ولاړ وو او د سوارۀ سره يې لينده وه. هغۀ ته تاج ورکړے شو او هغه د فاتح په حيث په آس سور لاړو چې فتح بيا مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29664, 'Revelation 6:3', 'Revelation', 6, 3, '&nbsp;کله چې ګډورى دوېم مهر مات کړو نو ما واورېدل چې دوېم جاندار وائى چې، ”راشه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29665, 'Revelation 6:4', 'Revelation', 6, 4, '&nbsp;او يو بل آس بهر راووتو چې تک سور وو او د هغۀ سوارۀ ته دا اختيار ورکړے شو چې د زمکې نه امن يوسى نو چې انسانان قتل و غارت شروع کړى، او هغۀ له يوه لويه تُوره ورکړے شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29666, 'Revelation 6:5', 'Revelation', 6, 5, '&nbsp;کله چې ګډُورى درېم مهر مات کړو نو ما د درېم جاندار دا آواز واورېدو چې، ”راشه.“ نو ما وليدو چې يو تور آس راغلو او د هغۀ د سوارۀ په لاس کښې يوه تله وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29667, 'Revelation 6:6', 'Revelation', 6, 6, '&nbsp;او ما د څلورو جاندارو د مينځه يو آواز واورېدو چې وئيل يې چې، ”د ورځې د مزدورۍ نرخ به د غنمو يوه روټۍ او يا به د اوربشو درې روټۍ وى، خو د زيتُونو تېلو او ميو ته نقصان مۀ رسوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29668, 'Revelation 6:7', 'Revelation', 6, 7, '&nbsp;کله چې ګډُورى څلورم مهر مات کړو نو ما د څلورم جاندار دا آواز واورېدو چې، ”راشه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29669, 'Revelation 6:8', 'Revelation', 6, 8, '&nbsp;ما وليدو چې زېړ آس وو او د سوارۀ نوم يې مرګ وو او عالمِ ارواح ورپسې جُخت راروان وو. هغوئ ته د څلورمې برخې زمکې اختيار ورکړے شوے وو چې په جنګ، په قحط، په وبا او ځنګلى ځناور خلق مړۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29670, 'Revelation 6:9', 'Revelation', 6, 9, '&nbsp;هر کله چې ګډُورى پينځم مهر مات کړو نو ما د قربان‌ګاه د لاندې د هغه ايماندارانو روحونه وکتل چې د خُدائ پاک د کلام او د خپلې ګواهۍ په وجه قتل کړے شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29671, 'Revelation 6:10', 'Revelation', 6, 10, '&nbsp;هغوئ په زوره چغه کړه چې، ”اے بادشاه مالِکه، پاکه او رښتونى خُدايه. ترڅو به تۀ فېصله نۀ کوې او د زمکې د اوسېدونکو نه به زمونږ د وينې بدل وانۀ خلې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29672, 'Revelation 6:11', 'Revelation', 6, 11, '&nbsp;بيا هر يو ته سپينه چُوغه ورکړے شوه او ورته يې ووئيل چې، ”تر هغې لږ صبر وکړئ چې په خِدمت کښې ستاسو ټول ملګرى ستاسو په شان ونۀ وژلے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29673, 'Revelation 6:12', 'Revelation', 6, 12, '&nbsp;بيا ما وکتل چې ګډُورى شپږم مهر مات کړو او يوه سخته زلزله راغله او نمر د تبخى په شان تور شو او سپوږمۍ مکمله لکه د وينو تکه سره شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29674, 'Revelation 6:13', 'Revelation', 6, 13, '&nbsp;او ستورى د آسمان نه په زمکه داسې راپرېوتل لکه چې د اينځر نه د سيلۍ طوفان په وجه کچه مېوه راپرېوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29675, 'Revelation 6:14', 'Revelation', 6, 14, '&nbsp;او آسمان داسې فنا شو لکه طومار چې بند کړے شى او هر غر او هره جزيره د خپله ځايه بې‌ځايه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29676, 'Revelation 6:15', 'Revelation', 6, 15, '&nbsp;نو بيا د زمکې بادشاهانو، سردارانو، جرنيلانو، مالدارانو، طاقتورو، غلامانو او آزادو ټولو خلقو په غارونو او د غرونو په ګټانو کښې خپل ځانونه پټ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29677, 'Revelation 6:16', 'Revelation', 6, 16, '&nbsp;او هغوئ غرونو او ګټانو ته چغې وهلې چې، ”په مونږ راپرېوځئ او مونږ د هغۀ د سترګو نه چې د تخت دپاسه ناست دے او د ګډُورى د قهر و غضب نه پټ کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29678, 'Revelation 6:17', 'Revelation', 6, 17, '&nbsp;ځکه چې د هغوئ د غضب لويه ورځ راغلې ده او څوک ورته ودرېدے شى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29679, 'Revelation 7:1', 'Revelation', 7, 1, '&nbsp;د دې نه پس ما څلور فرښتې د دُنيا په څلورو ګوټونو ولاړې وليدلې چې د دُنيا څلور واړه هواګانې يې قابو کړې وې نو چې په زمکه سمندر يا په يوه ونه هم هوا ونۀ لګى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29680, 'Revelation 7:2', 'Revelation', 7, 2, '&nbsp;بيا ما بله فرښته د نمرخاتۀ نه په راختو وليده چې د ژوندى خُدائ پاک مهر ورسره وو او هغه څلورو فرښتو ته يې په زوره وئيل، چې چا ته په زمکه او سمندر د نقصان ورکولو اختيار ورکړے شوے وو چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29681, 'Revelation 7:3', 'Revelation', 7, 3, '&nbsp;”تر هغې سمندر، زمکې او ونو ته نقصان مۀ رسوئ ترڅو چې مونږ د خُدائ پاک مُهر د هغۀ د خادِمانو په تندو نۀ وى لګولے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29682, 'Revelation 7:4', 'Revelation', 7, 4, '&nbsp;او ما چې د هغوئ شمېر واورېدو چا ته چې مهرونه لګولے شوى وُو او د بنى اِسرائيلو د ټولو خيلونو نه په يو لاک څلور څلوېښت زرو مُهر ولګولے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29683, 'Revelation 7:5', 'Revelation', 7, 5, '&nbsp;دولس زره د يهوداه د قبيلې نه، دولس زره د روبين د قبيلې نه، دولس زره د جاد د قبيلې نه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29684, 'Revelation 7:6', 'Revelation', 7, 6, '&nbsp;دولس زره د آشر د قبيلې نه، دولس زره د نفتالى د قبيلې نه، دولس زره د منسى د قبيلې نه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29685, 'Revelation 7:7', 'Revelation', 7, 7, '&nbsp;دولس زره د شمعون د قبيلې نه، دولس زره د ليوى د قبيلې نه، دولس زره د يساکار د قبيلې نه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29686, 'Revelation 7:8', 'Revelation', 7, 8, '&nbsp;دولس زره د زبولون د قبيلې نه، دولس زره د يوسف د قبيلې نه، او دولس زره د بنيامين د قبيلې وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29687, 'Revelation 7:9', 'Revelation', 7, 9, '&nbsp;او د دې نه پس ما د خلقو لويه ګڼه وليده چې بې‌شمېره وه، دا د ټولو قومونو، ټولو خيلونو او د مختلفو ژبو د ويوونکو خلقو ګڼه د تخت او د ګډُورى د وړاندې ولاړه وه. او هغوئ سپينې جامې اغوستې وې او د کجورو څانګې يې په لاسونو کښې نيولې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29688, 'Revelation 7:10', 'Revelation', 7, 10, '&nbsp;او په زوره يې دا چغې وهلې چې، ”خلاصون زمونږ د خُدائ پاک دے څوک چې په تخت ناست دے، او د ګډُورى دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29689, 'Revelation 7:11', 'Revelation', 7, 11, '&nbsp;او د تخت نه او د مشرانو او څلورو جاندارو نه چې ګېرچاپېره څومره فرښتې ولاړې وې هغه ټولې فرښتې د تخت په وړاندې پړمخې پرېوتلې او د خُدائ پاک عبادت يې وکړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29690, 'Revelation 7:12', 'Revelation', 7, 12, '&nbsp;هغوئ وئيل چې، ”آمين. برکت، لوئى، حِکمت، شُکر ګزارى، عزت، قُدرت او زور دې تل تر تله زمونږ د خُدائ پاک وى، آمين.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29691, 'Revelation 7:13', 'Revelation', 7, 13, '&nbsp;بيا مشرانو کښې يو ما ته مخ راواړولو او تپوس يې وکړو چې، ”دا خلق چې سپينې جامې يې اغوستې دى، څوک دى او د کومې راغلى دى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29692, 'Revelation 7:14', 'Revelation', 7, 14, '&nbsp;ما جواب ورکړو چې، ”زما مالِکه، تۀ خبر يې.“ بيا هغۀ ما ته وفرمائيل چې، ”دا هغه کسان دى چې د لوئ مصيبتونو نه راغلى دى، هغوئ خپلې جامې د ګډُورى په وينو وينځلې او په هغې سپينې کړې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29693, 'Revelation 7:15', 'Revelation', 7, 15, '&nbsp;په دې وجه خو دوئ د خُدائ پاک د تخت د وړاندې ولاړ دى او د خُدائ پاک په کور کښې شپه او ورځ د هغۀ په عبادت کښې لګيا دى، او هغه چې په تخت ناست دے، هغه به دوئ له پناه ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29694, 'Revelation 7:16', 'Revelation', 7, 16, '&nbsp;هغوئ به بيا هيڅکله نۀ اوږى کيږى، نۀ تږى کيږى، نمر به دوئ نۀ تنګوى او نۀ به تېزه ګرمى تکليف وررسوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29695, 'Revelation 7:17', 'Revelation', 7, 17, '&nbsp;ځکه چې هغه ګډُورے چې د تخت په مينځ کښې دے، هغه به د دوئ شپونکے وى او هغه به دوئ د ژوندون د اوبو چينو ته بوځى، او خُدائ پاک به د دوئ د سترګو نه ټولې اوښکې پاکې کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29696, 'Revelation 8:1', 'Revelation', 8, 1, '&nbsp;کله چې ګډُورى اوؤم مُهر کولاو کړو نو تقريباً تر نيمې ګينټې پورې په آسمان کښې خاموشى وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29697, 'Revelation 8:2', 'Revelation', 8, 2, '&nbsp;بيا ما هغه اووۀ فرښتې وليدلې چې د خُدائ پاک په وړاندې ولاړې وې، او هغوئ ته اووۀ بيګلونه ورکړے شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29698, 'Revelation 8:3', 'Revelation', 8, 3, '&nbsp;بيا يوه بله فرښته د سرو زرو مجمر په لاس راغله او د قربان‌ګاه سره ودرېده او هغې ته ډېره زياته خوشبوئى ورکړے شوه چې د تخت د وړاندې د سرو زرو په قربان‌ګاه يې د ټولو مقدسينو د دُعا سره پېش کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29699, 'Revelation 8:4', 'Revelation', 8, 4, '&nbsp;او د فرښتې د لاس نه د خوشبويۍ د سوزولو لوګے د مقدسينو د دُعا سره پاس خُدائ پاک ته ورسېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29700, 'Revelation 8:5', 'Revelation', 8, 5, '&nbsp;بيا فرښتې مجمر راواخستو، د قربان‌ګاه د اور نه يې ډک کړو او په زمکه يې راګزار کړو، نو بيا د تندر ګړزار، برېښنا او زلزله راغله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');